import numpy as np
import pandas as pd
from scipy.sparse import issparse

# Get more comprehensive view with key markers
cluster_ids = ['0', '3', '12', '18']
key_markers = ['GFAP', 'S100B', 'VIM', 'CD74', 'HLA-DRA', 'CD68', 'CD163', 'CSF1R', 
               'CD3D', 'CD3E', 'CD4', 'SPP1', 'CXCL8', 'B2M', 'HLA-A', 'CD44']

expr_dict = {cluster: {} for cluster in cluster_ids}

for cluster in cluster_ids:
    cluster_mask = adata.obs['leiden'] == cluster
    cluster_cells = adata[cluster_mask]
    if issparse(cluster_cells.X):
        cluster_mean = np.asarray(cluster_cells.X.mean(axis=0)).flatten()
    else:
        cluster_mean = cluster_cells.X.mean(axis=0)

    for gene in key_markers:
        if gene in adata.var_names:
            idx = list(adata.var_names).index(gene)
            expr_dict[cluster][gene] = cluster_mean[idx]

marker_df = pd.DataFrame(expr_dict).T
print("Comprehensive marker profile:")
print(marker_df.to_string())

# Calculate relative expression patterns
print("\n--- Relative expression (cluster mean / global mean) ---")
global_mean = {}
if issparse(adata.X):
    all_mean = np.asarray(adata.X.mean(axis=0)).flatten()
